import React from 'react';
import {
  Alert, Box, Button, Card, CardContent, Chip, Grid, LinearProgress, Skeleton, Stack, Typography,
} from '@mui/material';
import { CheckCircle, ErrorOutline, GitHub, Lock, ArrowForward, Shield, Language } from '@mui/icons-material';
import { motion } from 'framer-motion';
import { tokens } from '../../theme/tokens';
import { websiteCtaSx } from '../../theme/websiteChrome';
import { PUBLIC_ENGINE_CHIP_DISCONNECTED, PUBLIC_ENGINE_SCAN_COPY } from '../../data/publicInfrastructure';

export type HomeScanStatus = 'idle' | 'scanning' | 'complete' | 'error';

export type HomeScanReportData = {
  target?: string;
  score?: number;
  severity?: { critical?: number; high?: number; medium?: number; low?: number };
  algorithms?: Array<{ name: string; count?: number; quantumSafe?: boolean; attackClass?: string }>;
  quantumRisk?: string | number;
  resources?: Record<string, boolean>;
  detections?: Array<{ title: string; severity?: string; protocol?: string }>;
  qiskitEstate?: number;
  auditScore?: number;
  policyGate?: string;
};

type HomeScanReportProps = {
  status: HomeScanStatus;
  progress: number;
  report?: HomeScanReportData | null;
  onOpenApp: () => void;
  onRegister: () => void;
};

const STAGES = ['Connecting', 'Discovering files', 'Analyzing crypto', 'Building CBOM', 'Quantifying risk'];

const HomeScanReport: React.FC<HomeScanReportProps> = ({ status, progress, report, onOpenApp, onRegister }) => {
  const cardBg = '#0a0a0f';
  const activeStage = Math.min(STAGES.length - 1, Math.floor((progress / 100) * STAGES.length));

  return (
    <Box component={motion.div} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} sx={{ mb: 6 }}>
      <Card sx={{ bgcolor: cardBg, border: 1, borderColor: '#1f1f2e', color: '#fff' }}>
        <CardContent sx={{ p: { xs: 2.5, md: 3 } }}>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
            {/github/i.test(report?.target || '') ? <GitHub sx={{ color: tokens.colors.rivicq[500] }} /> : <Language sx={{ color: tokens.colors.rivicq[500] }} />}
            <Typography variant="h6" fontWeight={800}>CBOM scan</Typography>
            {status === 'scanning' && <Chip size="small" label="Running" color="primary" />}
            {status === 'complete' && <Chip size="small" label="Completed" color="success" />}
            {status === 'error' && <Chip size="small" label={PUBLIC_ENGINE_CHIP_DISCONNECTED} />}
          </Stack>

          {status === 'scanning' && (
            <Box>
              <LinearProgress variant={progress > 0 ? 'determinate' : 'indeterminate'} value={progress} sx={{ height: 8, borderRadius: 4, mb: 2 }} />
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
                {STAGES.map((s, i) => (
                  <Chip
                    key={s}
                    size="small"
                    icon={i <= activeStage ? <CheckCircle sx={{ fontSize: 14 }} /> : undefined}
                    label={s}
                    variant={i <= activeStage ? 'filled' : 'outlined'}
                    color={i <= activeStage ? 'primary' : 'default'}
                  />
                ))}
              </Stack>
              <Grid container spacing={2}>
                {[0, 1, 2].map((i) => (
                  <Grid item xs={12} sm={4} key={i}>
                    <Skeleton variant="rounded" height={72} sx={{ borderRadius: 2 }} />
                  </Grid>
                ))}
              </Grid>
            </Box>
          )}

          {status === 'complete' && report && (
            <Box>
              <Grid container spacing={2} sx={{ mb: 2 }}>
                <Grid item xs={6} sm={3}>
                  <Box sx={{ p: 1.5, borderRadius: 2, bgcolor: 'action.hover' }}>
                    <Typography variant="caption" color="text.secondary">Security score</Typography>
                    <Typography variant="h5" fontWeight={900} sx={{ color: tokens.colors.rivicq[600] }}>{report.score ?? report.auditScore ?? '—'}</Typography>
                  </Box>
                </Grid>
                {[
                  { k: 'critical', label: 'Critical', c: tokens.colors.crypto.critical },
                  { k: 'high', label: 'High', c: tokens.colors.crypto.high },
                  { k: 'medium', label: 'Medium', c: tokens.colors.crypto.medium },
                ].map((s) => (
                  <Grid item xs={6} sm={3} key={s.k}>
                    <Box sx={{ p: 1.5, borderRadius: 2, bgcolor: 'action.hover' }}>
                      <Typography variant="caption" color="text.secondary">{s.label}</Typography>
                      <Typography variant="h5" fontWeight={900} sx={{ color: s.c }}>
                        {(report.severity as Record<string, number | undefined>)?.[s.k] ?? 0}
                      </Typography>
                    </Box>
                  </Grid>
                ))}
              </Grid>
              {report.quantumRisk != null && report.quantumRisk !== '' && (
                <Alert icon={<Shield fontSize="inherit" />} severity="info" sx={{ mb: 2 }}>
                  Quantum exposure: <strong>{report.quantumRisk}</strong>
                  {report.qiskitEstate != null ? ` · Qiskit estate ${report.qiskitEstate}/100` : ''}
                  {report.policyGate ? ` · Policy ${report.policyGate}` : ''}
                </Alert>
              )}
              {report.resources && (
                <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
                  {Object.entries(report.resources).filter(([, on]) => on).map(([name]) => (
                    <Chip key={name} size="small" color="success" label={`${name.toUpperCase()} enabled`} />
                  ))}
                </Stack>
              )}
              {(report.detections?.length || 0) > 0 && (
                <Stack spacing={1} sx={{ mb: 2 }}>
                  {report.detections!.slice(0, 8).map((d, i) => (
                    <Typography key={`${d.title}-${i}`} variant="body2">
                      <strong>{(d.severity || 'info').toUpperCase()}</strong>
                      {d.protocol ? ` · ${d.protocol}` : ''} — {d.title}
                    </Typography>
                  ))}
                </Stack>
              )}
              {(report.algorithms?.length || 0) > 0 && (
                <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                  {report.algorithms!.slice(0, 10).map((a) => (
                    <Chip
                      key={a.name}
                      size="small"
                      icon={a.quantumSafe ? <CheckCircle sx={{ fontSize: 14 }} /> : <Lock sx={{ fontSize: 14 }} />}
                      label={a.count ? `${a.name} · ${a.count}` : a.attackClass ? `${a.name} · ${a.attackClass}` : a.name}
                      color={a.quantumSafe ? 'success' : 'default'}
                      variant="outlined"
                    />
                  ))}
                </Stack>
              )}
              <Button variant="contained" endIcon={<ArrowForward />} onClick={onOpenApp} sx={{ mt: 2, ...websiteCtaSx }}>
                Open full report
              </Button>
            </Box>
          )}

          {status === 'error' && (
            <Stack spacing={2}>
              <Alert severity="info" icon={<ErrorOutline fontSize="inherit" />}>
                {PUBLIC_ENGINE_SCAN_COPY}
              </Alert>
              <Stack direction="row" spacing={1.5} flexWrap="wrap" useFlexGap>
                <Button variant="contained" endIcon={<ArrowForward />} onClick={onRegister} sx={websiteCtaSx}>
                  Start free — run a real scan
                </Button>
                <Button variant="outlined" startIcon={<GitHub />} onClick={onOpenApp}>
                  Open the scanner
                </Button>
              </Stack>
            </Stack>
          )}
        </CardContent>
      </Card>
    </Box>
  );
};

export default HomeScanReport;
